namespace AdventOfCode01;

public static class RotationParser
{
    public static int ParseRotation(string item)
    {
        var digitWeNeed = new string(item.Skip(1).ToArray());
        var convertedDigit = int.Parse(digitWeNeed);
        return convertedDigit;
    }
}
public class RotationApplier
{
    private IUI UI { get; set; }
    public RotationApplier(IUI ui)
    {
        UI = ui;
    }
    public int ApplyRotation(ref int startDigit, string number)
    {
        int actualPosition = 0;

        if (number.StartsWith("R"))
        {
            ApplyRightRotation(ref startDigit, number);
        }
        else if (number.StartsWith("L"))
        {
            ApplyLeftRotation(ref startDigit, number);
        }
        else
        {
            UI.Write("No R or L found in this position.");
        }

        return actualPosition;
    }

    private void ApplyLeftRotation(ref int startDigit, string number)
    {
        int convertedDigit = RotationParser.ParseRotation(number);

        if (startDigit - convertedDigit < 0)
        {
            for (int i = 0; i < convertedDigit; i++)
            {
                if (startDigit == 0)
                {
                    startDigit = 99;
                }
                else
                {
                    startDigit--;
                }
            }
        }

        else
            startDigit -= convertedDigit;
    }

    private void ApplyRightRotation(ref int startDigit, string number)
    {
        int convertedDigit = RotationParser.ParseRotation(number);

        if (startDigit + convertedDigit > 99)
        {
            for (int i = 0; i < convertedDigit; i++)
            {
                if (startDigit == 99)
                {
                    startDigit = 0;
                }
                else
                {
                    startDigit++;
                }
            }
        }
        else
            startDigit += convertedDigit;
    }
}

